mapper.select:
SELECT id
FROM pets
WHERE user_id = #{userId}
  AND name = #{name}
  AND breed = #{breed}
ORDER BY id DESC
LIMIT 1

mapper.delete:
DELETE FROM reservations
WHERE reservation_code = #{reservationCode}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM reservations
WHERE room_id = #{roomId}
  AND status IN ('PAYMENT_PENDING', 'CONFIRMED', 'CHECKED_IN')
  AND checkin_date < #{checkOutDate}
  AND checkout_date > #{checkInDate}

SELECT COUNT(*)
FROM reservations
WHERE room_id = #{roomId}
  AND reservation_code != #{reservationCode}
  AND status IN ('PAYMENT_PENDING', 'CONFIRMED', 'CHECKED_IN')
  AND checkin_date < #{checkOutDate}
  AND checkout_date > #{checkInDate}
